export const asset=(name,size=24)=>`<span class="figma-icon" aria-hidden="true" style="--asset:url(assets/figma/${name}.svg);width:${size}px;height:${size}px"></span>`;
const icon=(name)=>asset(({back:'day-imgIconBack',pin:'day-imgIconPin',plane:'day-imgIconPlane',bag:'home-imgIconBag',people:'home-imgIconUsers',bell:'home-imgIconBell',more:'day-imgIconMore',check:'day-imgIconCheck'}[name])||'home-imgIconLink');
export const btn=(label,action='view',value='',kind='secondary',attrs='')=>`<button type="button" class="${kind}" data-action="${action}" data-value="${e(value)}" ${attrs}>${label}</button>`;
export const go=(view,label,kind='secondary',record='')=>btn(label,['Cancelar','Conservar viaje'].includes(label)?'back':['Agregar al recuerdo','Volver al recuerdo','Seguir explorando'].includes(label)?'return-view':'view',view,kind,record?`data-record="${e(record)}"`:'');
const row=(title,detail,view,record='',action='view')=>`<button type="button" class="list-row" data-action="${action}" data-value="${e(view)}" data-record="${e(record)}"><span><strong>${e(title)}</strong><small>${e(detail)}</small></span>${asset('home-imgIconArrow',20)}</button>`;
const field=(label,name,value='',type='text',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${e(value)}" ${extra}></label>`;
const select=(label,name,options,value,extra='')=>`<label class="field">${label}<select name="${name}" ${extra}>${options.map(([id,text])=>`<option value="${e(id)}" ${String(value)===String(id)?'selected':''}>${e(text)}</option>`).join('')}</select></label>`;
const textarea=(label,name,value='',extra='')=>`<label class="field">${label}<textarea name="${name}" ${extra}>${e(value)}</textarea></label>`;
const form=(id,body,label,submitAttrs='')=>`<form id="${id}" class="v1-form">${body}<p class="inline-error" role="alert" hidden></p><button class="primary" type="submit"${submitAttrs?' '+submitAttrs:''}>${label}</button></form>`;
const hint=copy=>`<p class="small-copy muted">${copy}</p>`,note=(title,copy)=>`<section class="inline-note"><h4>${title}</h4><p>${copy}</p></section>`;
const when=(date,time,prefix='')=>`<div class="when-fields">${field('Fecha local',prefix+'date',date,'date','required')}${field('Hora local',prefix+'time',time,'time','required step="0.001"')}</div>`;
const activityTime=activityTimeLabel;
const decisionBadge=(a,userId='nico')=>a.decisionRequired?.[userId]?btn('Modificado','decision-info',a.id,'decision-badge', 'aria-label="Modificado: revisá tu participación"'):'';
const durationFields=d=>'<fieldset class="duration-fields"><legend>Duración estimada · opcional</legend><div class="when-fields">'+field('Horas','durationHours',d.durationHours??'','number','min="0" step="1" inputmode="numeric" placeholder="0"')+field('Minutos','durationMinutesPart',d.durationMinutesPart??'','number','min="0" max="59" step="1" inputmode="numeric" placeholder="0"')+'</div></fieldset>';
export const spontaneousDefaults=(now=new Date().toISOString())=>({date:localDate(now),time:localTime(now)});
export function calendarEntries(t){
 const days=t.destinations.flatMap(d=>{
  const w=destinationWindow(t,d.id);if(!w.arrival||!w.departure)return [];
  const entries=[],day=new Date(localDate(w.arrival)+'T00:00');
  for(let i=0;localDate(day)<=localDate(w.departure)&&i<366;i++){
   const date=localDate(day),next=new Date(day);next.setDate(next.getDate()+1);
   const start=new Date(Math.max(Date.parse(w.arrival),day.getTime())).toISOString();
   const end=new Date(Math.min(Date.parse(w.departure),next.getTime())).toISOString();
   if(Date.parse(end)>Date.parse(start))entries.push({id:'day-'+d.id+'-'+date,kind:'day',title:t.name+' · '+d.name,start,end,place:d.name});
   day.setDate(day.getDate()+1);
  }
  return entries;
 });
 return [...days,...t.activities.map(a=>({id:a.id,kind:'activity',title:t.name+' · '+a.title,start:a.scheduledAt,end:activityEnd(a),place:a.place||t.destinations.find(d=>d.id===a.destinationId)?.name||''}))];
}
const participationPanel=(a,t)=>{
 const own=a.participations.nico,going=t.members.filter(m=>a.participations[m.id]==='going'),pending=t.members.filter(m=>!a.participations[m.id]||a.participations[m.id]==='pending'),notGoing=t.members.filter(m=>a.participations[m.id]==='not_going');
 return `<section class="response-section"><h4>¿Vas a participar?</h4>${decisionBadge(a)}<div class="response-buttons" role="group" aria-label="Tu participación">${['going','not_going'].map((x,i)=>btn(i?'No voy':'Voy','participation',x,own===x?'primary':'secondary',`aria-pressed="${own===x}"`)).join('')}</div>${hint(own==='going'?'Vas a participar.':own==='not_going'?'No vas a participar.':'Sin responder. Elegí si te sumás al plan.')}<div class="group-response">${going.map(m=>avatar(m.name)).join('')}<p class="small-copy muted">${going.length?going.length+' '+(going.length===1?'va':'van'):'Sin participantes'} · ${pending.length} sin responder · ${notGoing.length} no van</p></div><div class="participant-list">${t.members.map(m=>`<p><strong>${e(m.id==='nico'?'Vos':m.name)}</strong><span>${({going:'Voy',not_going:'No voy'})[a.participations[m.id]]||'Sin responder'}</span></p>`).join('')}</div></section>`;
};
const initials=name=>name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();
